import * as React from "react";

interface CarouselArrowProps {
  direction: "prev" | "next";
  onClick: () => void;
  className?: string;
}

const CarouselArrow: React.FC<CarouselArrowProps> = ({ direction, onClick, className = "" }) => {
  const isPrev = direction === "prev";

  return (
    <button
      onClick={onClick}
      aria-label={isPrev ? "Previous image" : "Next image"}
      className={`group hidden sm:flex shrink-0 w-10 h-10 items-center justify-center ${className}`}
    >
      <svg
        width="30"
        height="22"
        viewBox="0 0 30 22"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
        aria-hidden="true"
        className={`transition-all duration-200 ${isPrev ? "rotate-[270deg]" : "rotate-90"}`}
      >
        <path
          d="M1.16776 17.875L14.9178 4.125L28.6678 17.875"
          stroke="currentColor"
          strokeWidth="1"
          className="transition-all duration-200 group-hover:stroke-[2.5] group-hover:opacity-70"
        />
      </svg>
    </button>
  );
};

export default CarouselArrow;
